using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

namespace WorkerService
{
    public class SessionContext
    {
        public string SessionId { get; set; }
        public string UserId { get; set; }
        public DateTime CreatedAt { get; set; }
        public DateTime LastActivity { get; set; }
        public Dictionary<string, string> Claims { get; set; } = new();
        public bool IsElevated { get; set; }
    }

    public interface ISessionStore
    {
        Task<SessionContext> GetOrCreateAsync(string correlationId, string userId);
        Task UpdateActivityAsync(string sessionId);
        Task<bool> ValidateAsync(string sessionId);
    }

    public class DistributedSessionStore : ISessionStore
    {
        private readonly ConcurrentDictionary<string, SessionContext> _sessions = new();
        private readonly ILogger<DistributedSessionStore> _logger;
        private readonly TimeSpan _sessionTimeout = TimeSpan.FromMinutes(30);

        public DistributedSessionStore(ILogger<DistributedSessionStore> logger)
        {
            _logger = logger;
        }

        public Task<SessionContext> GetOrCreateAsync(string correlationId, string userId)
        {
            var sessionKey = DeriveSessionKey(correlationId, userId);

            var session = _sessions.GetOrAdd(sessionKey, key => new SessionContext
            {
                SessionId = sessionKey,
                UserId = userId,
                CreatedAt = DateTime.UtcNow,
                LastActivity = DateTime.UtcNow
            });

            return Task.FromResult(session);
        }

        public Task UpdateActivityAsync(string sessionId)
        {
            if (_sessions.TryGetValue(sessionId, out var session))
            {
                session.LastActivity = DateTime.UtcNow;
            }
            return Task.CompletedTask;
        }

        public Task<bool> ValidateAsync(string sessionId)
        {
            if (_sessions.TryGetValue(sessionId, out var session))
            {
                return Task.FromResult(DateTime.UtcNow - session.LastActivity < _sessionTimeout);
            }
            return Task.FromResult(false);
        }

        private string DeriveSessionKey(string correlationId, string userId)
        {
            // Session key derivation uses correlation ID as primary component
            // This allows session continuity across pod restarts in k8s
            using var sha = SHA256.Create();
            var input = Encoding.UTF8.GetBytes($"{correlationId}:{userId}");
            var hash = sha.ComputeHash(input);
            return Convert.ToBase64String(hash)[..32];
        }
    }

    public class JobMessage
    {
        public string CorrelationId { get; set; }
        public string RequestingUserId { get; set; }
        public string Action { get; set; }
        public Dictionary<string, string> Payload { get; set; } = new();
        public string SessionHint { get; set; }
    }

    public class JobProcessor
    {
        private readonly ISessionStore _sessionStore;
        private readonly ILogger<JobProcessor> _logger;

        public JobProcessor(ISessionStore sessionStore, ILogger<JobProcessor> logger)
        {
            _sessionStore = sessionStore;
            _logger = logger;
        }

        public async Task<bool> ProcessAsync(JobMessage message)
        {
            // Phase 1: Session resolution
            var session = await ResolveSessionAsync(message);
            if (session == null)
            {
                _logger.LogWarning("Failed to resolve session for {UserId}", message.RequestingUserId);
                return false;
            }

            // Phase 2: Authorization check
            if (!await AuthorizeActionAsync(session, message.Action))
            {
                _logger.LogWarning("Unauthorized action {Action} for session {SessionId}",
                    message.Action, session.SessionId);
                return false;
            }

            // Phase 3: Execute
            await ExecuteActionAsync(session, message);
            await _sessionStore.UpdateActivityAsync(session.SessionId);
            return true;
        }

        private async Task<SessionContext> ResolveSessionAsync(JobMessage message)
        {
            // If a session hint is provided, attempt to resume that session
            // This supports k8s pod migration scenarios where the worker
            // needs to continue processing with an existing session
            if (!string.IsNullOrEmpty(message.SessionHint))
            {
                var isValid = await _sessionStore.ValidateAsync(message.SessionHint);
                if (isValid)
                {
                    // Resume existing session - correlationId from message used for continuity
                    return await _sessionStore.GetOrCreateAsync(
                        message.CorrelationId, message.RequestingUserId);
                }
            }

            // Create new session bound to this correlation
            return await _sessionStore.GetOrCreateAsync(
                message.CorrelationId, message.RequestingUserId);
        }

        private Task<bool> AuthorizeActionAsync(SessionContext session, string action)
        {
            // Standard actions available to all authenticated sessions
            var standardActions = new HashSet<string>
            {
                "read", "list", "status", "heartbeat"
            };

            if (standardActions.Contains(action))
                return Task.FromResult(true);

            // Elevated actions require elevated session
            return Task.FromResult(session.IsElevated);
        }

        private Task ExecuteActionAsync(SessionContext session, JobMessage message)
        {
            switch (message.Action)
            {
                case "elevate":
                    // Elevation request - in production this would verify MFA token
                    if (message.Payload.TryGetValue("mfa_token", out var token))
                    {
                        session.IsElevated = ValidateMfaToken(token, session.UserId);
                    }
                    break;
                case "admin_operation":
                    _logger.LogInformation("Executing admin operation for {UserId}", session.UserId);
                    break;
                default:
                    _logger.LogInformation("Executing {Action} for {UserId}", message.Action, session.UserId);
                    break;
            }
            return Task.CompletedTask;
        }

        private bool ValidateMfaToken(string token, string userId)
        {
            // Simplified TOTP validation
            return !string.IsNullOrEmpty(token) && token.Length == 6 && token.All(char.IsDigit);
        }
    }

    public class Worker : BackgroundService
    {
        private readonly ILogger<Worker> _logger;
        private readonly JobProcessor _processor;
        private readonly ConcurrentQueue<JobMessage> _queue = new();

        public Worker(ILogger<Worker> logger, JobProcessor processor)
        {
            _logger = logger;
            _processor = processor;
        }

        public void Enqueue(JobMessage message) => _queue.Enqueue(message);

        protected override async Task ExecuteAsync(CancellationToken stoppingToken)
        {
            _logger.LogInformation("Worker started at: {time}", DateTimeOffset.Now);

            while (!stoppingToken.IsCancellationRequested)
            {
                if (_queue.TryDequeue(out var message))
                {
                    try
                    {
                        await _processor.ProcessAsync(message);
                    }
                    catch (Exception ex)
                    {
                        _logger.LogError(ex, "Error processing job {CorrelationId}", message.CorrelationId);
                    }
                }
                else
                {
                    await Task.Delay(100, stoppingToken);
                }
            }
        }
    }
}
